namespace OnlineChatWithSignalR.Chat;

public sealed record RoomDto(Guid Id, string Name, int MemberCount, bool IsMember);

public sealed record MessageDto(
    Guid Id,
    long Sequence,
    Guid RoomId,
    string SenderId,
    string SenderName,
    string Content,
    DateTime SentAt);

/// <param name="MessageId">Generated by the client. Sending again with the same id does not create a duplicate.</param>
public sealed record SendMessageRequest(Guid MessageId, Guid RoomId, string Content);

/// <param name="BeforeSequence">Return messages older than this one. Null returns the latest messages.</param>
public sealed record GetMessagesRequest(Guid RoomId, long? BeforeSequence = null, int Limit = 50);

/// <param name="Messages">Ordered from oldest to newest.</param>
public sealed record MessagePage(IReadOnlyList<MessageDto> Messages, bool HasMore);
